      <div class="preview-scroll"><div id="preview" class="preview-content"></div></div>
    </section>

    <div class="split-tools">
      <button class="btn" title="Editor only">▣</button>
      <button class="btn" title="Split view">◫</button>
      <button class="btn" title="Preview only">◉</button>
    </div>
    <div class="divider"><div class="handle"></div></div>
